export class Builder {
  // The popup window that hosts the custom widget builder
  builderWindow: Window | null;

  // Map of message type -> list of registered callbacks
  onMessageMap: Record<string, MessageCallback[]> = {};

  // Reference to the bound message listener so it can be removed later
  private messageListener: (event: MessageEvent) => void;

  constructor() {
    this.builderWindow = window.open(
      `${window.location.pathname}/builder`,
      "_blank",
    );

    this.messageListener = (event: MessageEvent) => {
      if (event.source === this.builderWindow) {
        const handlerList = this.onMessageMap[event.data.type];

        if (handlerList) {
          handlerList.forEach((fn) => fn(event.data));
        }
      }
    };

    window.addEventListener("message", this.messageListener);
  }

  onMessage(type: string, callback: MessageCallback) {
    if (!this.onMessageMap[type]) {
      this.onMessageMap[type] = [];
    }

    this.onMessageMap[type].push(callback);

    // Return a function that cancels this specific listener
    return () => {
      this.onMessageMap[type] = this.onMessageMap[type].filter(
        (fn) => fn !== callback,
      );
    };
  }

  postMessage(message: unknown) {
    this.builderWindow?.postMessage(message, "*");
  }

  isConnected() {
    return Boolean(this.builderWindow && !this.builderWindow.closed);
  }

  focus() {
    if (this.isConnected()) {
      this.builderWindow?.focus();
    }
  }

  close(closeWindow = false) {
    window.removeEventListener("message", this.messageListener);

    if (closeWindow) {
      this.builderWindow?.close();
    }
  }
}

class CustomWidgetBuilderService {
  // Builder instances keyed by widget id
  private builderMap: Map<string, Builder> = new Map();

  // Factory used to create Builder instances. Overridable for testing.
  private builderFactory: () => Builder = () => new Builder();

  setBuilderFactory(factory: () => Builder) {
    this.builderFactory = factory;
  }

  createBuilder(widgetId: string) {
    const builder = this.builderFactory();

    this.builderMap.set(widgetId, builder);

    return builder;
  }

  isConnected(widgetId: string) {
    const builder = this.builderMap.get(widgetId);

    return Boolean(builder && builder.isConnected());
  }

  focus(widgetId: string) {
    const builder = this.builderMap.get(widgetId);

    if (builder) {
      builder.focus();
    }
  }

  closeBuilder(widgetId: string, closeWindow = false) {
    const builder = this.builderMap.get(widgetId);

    if (builder) {
      builder.close(closeWindow);
      this.builderMap.delete(widgetId);
    }
  }

  getBuilder(widgetId: string) {
    return this.builderMap.get(widgetId);
  }
}

export default new CustomWidgetBuilderService();
